/**
 * Captions Studio test 58, part P4's share (docs/design/captions-studio.md §6.9, §11): the data
 * notice credits what is generated into src/shared/captions from dev dependencies (Unicode,
 * obscenity, LDNOOBW), and every generated file names its source, version and licence at its top.
 */
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'

const ROOT = path.join(__dirname, '..')
const read = (file: string): string => readFileSync(path.join(ROOT, file), 'utf8')

describe('the caption data notice and the generated files (test 58)', () => {
  it('has the LDNOOBW attribution parts, the Unicode licence and obscenity', () => {
    const notice = read('resources/notices/35-caption-data.txt')
    for (const part of [
      '© 2012–2020 Shutterstock, Inc.',
      'Creative Commons Attribution 4.0 International',
      'https://creativecommons.org/licenses/by/4.0/',
      'https://github.com/LDNOOBW/List-of-Dirty-Naughty-Obscene-and-Otherwise-Bad-Words',
      "Modified: lower-cased, filtered and merged with Flown's own lists.",
      'Copyright © 1991-2026 Unicode, Inc.',
      'obscenity 0.4.6',
      'Joseph Liu'
    ])
      expect(notice.includes(part), part).toBe(true)
    // The notices file shipped with the app carries it.
    expect(read('resources/THIRD_PARTY_NOTICES.txt').includes('© 2012–2020 Shutterstock, Inc.')).toBe(true)
  })

  it('every generated file starts with a header naming its source, version and licence; the team lists are CC0-1.0', () => {
    const headers: Record<string, RegExp[]> = {
      'src/shared/captions/bleepWords.ts': [/obscenity 0\.4\.6/, /MIT/, /naughty-words/, /CC BY 4\.0/],
      'src/shared/captions/emojiData.ts': [/CLDR 49\.0\.0/, /Unicode/, /CC0-1\.0/],
      'src/shared/captions/numberData.ts': [/CLDR 49\.0\.0/, /cldr-rbnf/, /Unicode/]
    }
    for (const [file, wants] of Object.entries(headers)) {
      const head = read(file).slice(0, 1500)
      expect(head.startsWith('/**\n * GENERATED by scripts/build-emoji-data.mjs'), file).toBe(true)
      for (const w of wants) expect(w.test(head), `${file}: ${w}`).toBe(true)
    }
    expect(read('src/shared/captions/stopWords.ts').slice(0, 600)).toContain('Written for Flown, CC0-1.0')
  })
})
